    let ay;
    let dx;
    let dy;
    let uatk = schar((cptr.eq(magr, cptr.add(gy, $instance_globals_y_youmonst))));
    let udef = schar((cptr.eq(mdef, cptr.add(gy, $instance_globals_y_youmonst))));

